                    <a id="files-up-link" href="#" onclick="navigateUp(event)">&#8593; Back to Parent</a>
                </div>
            </div>
            <div id="file-list"></div>
        </div>
    </div>

    <!-- Notepad Window -->
    <div id="notepad-window" class="window">
        <div class="title-bar" onmousedown="startDrag(event, 'notepad-window')">
            <span style="pointer-events: none;">Text Editor</span>
            <button class="win-close" onclick="closeWindow('notepad-window')">×</button>
        </div>
        <div class="window-content">
            <div class="tab-strip">
                <div id="tabs"></div>
                <button id="new-tab-btn">&#43;</button>
            </div>
            <div id="editor-container">
                <textarea id="editor" placeholder="Start typing..."></textarea>
            </div>
        </div>
    </div>

</div>

<script>
/** 
 * State Management & File System Structure
 */
const FILE_SYSTEM = {
    name: '/', type: 'root', children: {}
};

// Build the required structure manually
function createNode(name, isDir) { return { name, type: isDir ? 'dir' : 'file', children: {}, content: '' }; }

FILE_SYSTEM.children['bin'] = createNode('bin', true);
FILE_SYSTEM.children['etc'] = createNode('etc', true);
FILE_SYSTEM.children['usr'] = createNode('usr', true);
FILE_SYSTEM.children['var'] = createNode('var', true);

// /home
const homeDir = FILE_SYSTEM.children['home'];
homeDir.children = {};
homeDir.children['user'] = createNode('user', true);
const userDir = homeDir.children['user'];
userDir.children = {};

// /home/user contents
userDir.children['Documents'] = createNode('Documents', true);
userDir.children['Downloads'] = createNode('Downloads', true);
userDir.children['Pictures'] = createNode('Pictures', true);
// Add a sample file for realism
userDir.children['notes.txt'] = createNode('notes.txt', false, 'Hello World');

let currentPath = []; // Array of objects representing path from root to current (excluding self) -> actually simpler: array of child keys.
// Root is empty array or ['']? Let's treat root as special index 0 pointing to FILE_SYSTEM object directly, and navigate via indices.
// For rendering list items based on a path string like "/home/user", we need lookup logic.

function getDir(pathString) {
    if (pathString === '/' || pathString === '') return FILE_SYSTEM;
    const parts = pathString.split('/').filter(p => p !== '');
    let current = FILE_SYSTEM.children[parts[0]];
    for(let i=1; i<parts.length; i++) {
        if(!current) break; // Should not happen in valid logic but safe guard
        current = current.children[parts[i]];
    }
    return current || null;
}

// State: Current path string (e.g. '/home/user')
let filesCurrentPathStr = ''; 
if(filesCurrentPathStr === '') { // Init if empty
   // Wait for load, but default to root '/'
   navigateTo('/');
}


/** Notepad State */
const NOTEPAD_STORAGE_KEY = 'ubuntu_notepad_tabs';

class TabState {
    constructor(id) { this.id = id; this.content = ''; }
    save() { localStorage.setItem(NOTEPAD_STORAGE_KEY, JSON.stringify(allTabs.map(t => ({id: t.id, content: t.content})))); }
}
let allTabs = [];
let activeTabId = null;

function initNotepad() {
    // Load from storage
    const saved = localStorage.getItem(NOTEPAD_STORAGE_KEY);
    if(saved) {
        try {
            const data = JSON.parse(saved);
            // We must re-create TabState objects, not just plain objects
            allTabs = data.map(d => new TabState(d.id));
            activeTabId = (allTabs.length > 0) ? allTabs[0].id : null;
        } catch(e) { console.error("Notepad load fail", e); }
    }
    if(allTabs.length === 0) createNewTab(); // Ensure at least one tab on init

    renderTabsUI();
}

function createNewTab() {
    const id = Date.now().toString(36);
    allTabs.push(new TabState(id));
    activeTabId = id;
    saveNotepad();
    renderTabsUI();
}

function switchTab(id) {
    if(!allTabs.some(t => t.id === id)) return; // Ensure valid tab exists (recovery)
    activeTabId = id;
    document.getElementById('editor').value = allTabs.find(t => t.id === id).content;
    renderTabsUI();
}

function saveNotepad() {
    const currentContent = document.getElementById('editor').value;
    const tab = allTabs.find(t => t.id === activeTabId);
    if(tab) {
        tab.content = currentContent;
        localStorage.setItem(NOTEPAD_STORAGE_KEY, JSON.stringify(allTabs.map(t => ({id: t.id, content: t.content}))));
    }
}

// Notepad Event Listeners
document.getElementById('new-tab-btn').addEventListener('click', createNewTab);
const editorInput = document.getElementById('editor');
editorInput.addEventListener('input', saveNotepad); 
// Also auto-save on blur or close just in case, but 'input' is main.


/** File System UI Logic */

function navigateTo(pathStr) {
    filesCurrentPathStr = pathStr;
    // Update Path Display (e.g., " / home user")
    const parts = pathStr.split('/').filter(p => p !== '');
    let htmlParts = [];

    if(parts.length === 0 || (parts[0] === '' && parts.length===1)) { 
        // Root case: "/"
        document.getElementById('files-path').innerText = "/";
        renderFileList(FILE_SYSTEM);
    } else {
        // Construct " / ... / current"
        let accPath = [];
        for(let p of parts) {
            if(p === '') continue; 
            const partNode = getDir('/' + accPath.join('/') + '/' + p).parent ? null : FILE_SYSTEM.children[p];

            // Build string
            htmlParts.push(p);
            document.getElementById('files-path').innerText = '/ ' + htmlParts.join(' / ');

            if(parts.indexOf(p) === parts.length - 1) {
                const dirNode = getDir('/' + p).parent ? null : FILE_SYSTEM.children[p]; // simplified lookup below...

                // Better: just traverse to ensure validity of current folder object before rendering
            }
        }

        const targetDirObj = getDir(pathStr);
        if(targetDirObj && targetDirObj.name) {
             document.getElementById('files-path').innerText = pathStr === '/' ? '/' : pathStr; // simplified display logic handled by the loop below effectively.

             renderFileList(getDir(pathStr));
        } else {
            alert("Could not load directory");
            return;
        }
    }
}

// Helper to get parent dir of current path for Up Button
function getParentDirObj(pathStr) {
    if (pathStr === '/' || !pathStr.includes('/')) return null; // Root has no parent in this context
    const parts = pathStr.split('/').filter(p => p !== '');
    const lastPart = parts.pop(); // remove current folder name
    const dirPath = parts.length ? '/' + parts.join('/') : '/';
    return getDir(dirPath);
}

function navigateUp(event) {
    event.preventDefault();
    if(filesCurrentPathStr === '/') return; // Already at root

    const parentObj = getParentDirObj(filesCurrentPathStr);
    if(parentObj && parentObj.name !== undefined) {
        let newPath = '/';

        // Calculate path string for parent relative to structure? 
        // My FILE_SYSTEM is flat object keyed by name under children.
        // To generate correct path string, I need reverse lookup logic or simply store it in state variable `currentDirObj`.
        // Simpler: just manually construct based on parts.

        const currentParts = filesCurrentPathStr.split('/').filter(p => p !== '');
        if(currentParts.length > 0) {
            currentParts.pop(); // Remove last part

            let newPathStr = '/' + currentParts.join('/');
            navigateTo(newPathStr);
        } else {
             navigateTo('/'); 
        }

    }
}


function renderFileList(dirObj) {
    const listEl = document.getElementById('file-list');
    listEl.innerHTML = ''; // clear existing

    if(!dirObj || !dirObj.children) return; // Should not happen with valid checks

    for(const key in dirObj.children) {
        const node = dirObj.children[key];

        const itemDiv = document.createElement('div');
        itemDiv.className = 'fs-item';
        itemDiv.innerHTML = `<div class="fs-icon">${node.type === 'dir' ? '&#128193;' : '&#128196;'}</div><span>${key}</span>`; // Folder icon or File

        if(node.type === 'dir') {
            itemDiv.addEventListener('dblclick', () => {
                const newPath = filesCurrentPathStr + (filesCurrentPathStr.endsWith('/') ? '' : '/') + key;
                navigateTo(newPath);
            });
        } else {
             // File click just logs to console in this demo, maybe select file?
        }

        listEl.appendChild(itemDiv);
    }
}


/** Window Management */
let windows = {};

function openWindow(id) {
    const el = document.getElementById(id);
    if(!el) return;

    // Ensure visible
    el.style.display = 'flex';

    // Initial centering (if hidden before or just to look nice)
    windowPosition(el, 100 + (Object.keys(windows).length * 20), 50);

    windows[id] = { element: el };
}

function closeWindow(id) {
    const el = document.getElementById(id);
    if(!el) return;

    // If Notepad, ensure save before hide? Already saving on input. 
    // Save state logic for notepad handled via events mostly.
    if (id === 'notepad-window') {
        // Double check active tab saved to localstorage already by event listener
        // But sometimes user closes without typing; it's safe because default is empty string in newTab created.
    }

    el.style.display = 'none';
}


// Drag Logic (Global)
let draggedEl = null;
let initialPos = {x:0, y:0};

function startDrag(e, windowId) {
    if(windowId === 'notepad-window' && e.target.closest('.tab')) return; // Don't drag when clicking tab

    const el = document.getElementById(windowId);
    if(!el || !e.buttons) return; 

    draggedEl = el;

    initialPos.x = e.clientX - el.offsetLeft;
    initialPos.y = e.clientY - el.offsetTop;

    // Bring to front
    el.style.zIndex = 1000 + Object.keys(windows).length * 10;

    document.addEventListener('mousemove', dragWindow);
    document.addEventListener('mouseup', stopDrag);
}

function dragWindow(e) {
    if(!draggedEl) return;

    // Prevent dragging out of bounds too much (optional but good)
    let x = e.clientX - initialPos.x;
    let y = e.clientY - initialPos.y;

    // Simple boundary check to keep inside viewport roughly
    const maxX = document.body.clientWidth - draggedEl.offsetWidth + 50; 
    if(x < -20) x = -20;

    draggedEl.style.left = x + 'px';
    draggedEl.style.top = y + 'px';
}

function stopDrag() {
    document.removeEventListener('mousemove', dragWindow);
    document.removeEventListener('mouseup', stopDrag);
    draggedEl = null;

    // Reset Z-Index slightly to keep order relative? Not strictly needed.
}


/** Main Initialization */
document.addEventListener('DOMContentLoaded', () => {
    initNotepad();

    /** Launcher Listeners */
    const openFilesBtn = document.getElementById('open-files');
    if(openFilesBtn) openFilesBtn.onclick = () => openWindow('files-window');

    const openNoteBtn = document.getElementById('open-notepad');
    if(openNoteBtn) openNoteBtn.onclick = () => { 
        // If notepad is hidden, ensure it opens visible.
        openWindow('notepad-window'); 

        // Ensure there's content to display immediately (active tab)
        renderTabsUI(); 
    };

    /** Initial File System Load */
    navigateTo('/'); 

});


// Notepad UI Render Helper
function renderTabsUI() {
    const tabsContainer = document.getElementById('tabs');

    // Re-render all tabs to sync with state
    tabsContainer.innerHTML = '';

    if(allTabs.length === 0) return;

    let indexToFocus = null; // Keep track of which one gets focus visually (active)

    for(let t of allTabs) {
        const tabEl = document.createElement('div');
        tabEl.className = 'tab';
        tabEl.innerText = `Tab ${allTabs.indexOf(t)+1}`; // Simplified naming

        if(t.id === activeTabId) {
            tabEl.classList.add('active');
            indexToFocus = tabsContainer.children.length - 1;

            // Sync textarea content on render (if switching view, ensure display matches)
            document.getElementById('editor').value = t.content;
        }

        tabEl.addEventListener('click', () => switchTab(t.id));

        // Add close button to tabs? Not strictly required but good. 
        // Prompt only says "All tabs and their content persist...". Basic implementation is fine.
        tabsContainer.appendChild(tabEl);
    }

    if(indexToFocus !== null) {
        document.getElementById('editor').value = allTabs.find(t => t.id === activeTabId).content;
    }
}

// Ensure window positions are set correctly on open so they aren't lost behind taskbar or offscreen.
function windowPosition(el, left = 50, top = 50) {
    el.style.left = left + 'px';
    el.style.top = top + 'px';
}

</script>
</body>
